mapper.insert:
SELECT seq_posts.NEXTVAL FROM dual
BEGIN INSERT INTO posts ( post_id, user_id, caption, translated_caption, created_at, updated_at ) VALUES ( #{postId}, #{userId}, #{caption, jdbcType=VARCHAR}, #{translatedCaption, jdbcType=VARCHAR}, SYSTIMESTAMP, SYSTIMESTAMP );
INSERT INTO post_media ( media_id, post_id, media_type, media_url, sort_order, original_file_name, created_at ) VALUES ( seq_post_media.NEXTVAL, #{postId}, #{media.type, jdbcType=VARCHAR}, #{media.url, jdbcType=VARCHAR}, #{media.sortOrder, jdbcType=INTEGER}, #{media.originalFileName, jdbcType=VARCHAR}, SYSTIMESTAMP );
END;
